    "classes": "Ocultista",
    "ritual": false,
    "concentration": true,
    "desc": "Você escolhe uma criatura que possa ver dentro do alcance e anima a sombra dela, colocando-a sob seu controle. A magia falha se a criatura possuir ND superior a 3 ou não projetar sombra, seja por sua própria natureza ou pela ausência de uma fonte de luz. Criaturas sem ND, como personagens dos jogadores, são imunes a esta magia.\n\nCaso contrário, uma cópia da criatura é criada em um espaço adjacente a ela, no lado oposto à fonte de luz mais intensa nas proximidades, usando as estatísticas de jogo da criatura original. A sombra não possui ações lendárias nem Resistência Lendária e não pode conjurar magias. Ela possui pontos de vida iguais à metade dos pontos de vida do alvo e parece uma versão espelhada da criatura, formada por fumaça negra e densa.\n\nEnquanto estiver na escuridão, a sombra tem resistência a dano contundente, cortante e perfurante de fontes não mágicas. Enquanto estiver sob luz plena, ela possui vulnerabilidade a todos os tipos de dano, e é sempre vulnerável a dano de fogo, elétrico e radiante. Se a sombra for destruída, a criatura da qual foi criada deixa de projetar sombra pelas próximas 8 horas.\n\nA sombra age imediatamente após o turno da criatura original. Sem outra orientação, ela tenta seguir a criatura da qual foi criada e realiza a ação Atacar contra ela. Quando a sombra começa o turno, você pode usar sua reação para assumir seu controle e fazer com que ela se mova e realize a ação que você determinar.",
    "higher": "Ao conjurar esta magia usando um espaço de 5º ou 6º nível, o ND máximo do alvo aumenta para 4. Com um espaço de 7º ou 8º nível, aumenta para 5. Com um espaço de 9º nível, aumenta para 6.",
