    "ritual": false,
    "concentration": false,
    "desc": "Você cria um plano de força luminosa em forma de espada, que flutua em um espaço dentro do alcance e permanece pela duração. Quando a espada surge e, nos turnos seguintes, como uma ação bônus, você pode dar a ela um dos comandos abaixo:\n\n• Atacar. A espada se move até 6 metros em direção a uma criatura e a ataca. Realize um ataque corpo a corpo com magia. Em caso de acerto, o alvo sofre 3d10 + seu modificador de habilidade de conjuração de dano de força.\n• Guardar. A espada se move até 6 metros em direção a uma criatura. Enquanto compartilhar o espaço dela, concede meia cobertura à criatura ao tentar desviar ataques recebidos. Na primeira vez que uma criatura hostil chegar a até 1,5 metro da espada, ela ataca essa criatura com um ataque corpo a corpo com magia. Em caso de acerto, o alvo sofre 3d10 + seu modificador de habilidade de conjuração de dano de força. A espada não pode atacar novamente até receber outro comando.\n• Rodopiar. A espada se move até 6 metros em direção a um ponto e começa a girar de forma mortal ao alcançá-lo. Uma criatura que começar seu turno no espaço da espada ou entrar pela primeira vez em seu turno a até 1,5 metro dela deve ser bem-sucedida em um teste de resistência de Destreza ou sofrer 3d10 de dano de força.\n\nNotas de Caius: A Verdadeira Versão Perdida. Esta é a verdadeira versão da famosa espada mágica flutuante de um mago. Tragicamente, a maioria das fontes registra uma versão incompleta, copiada por um aprendiz incapaz de compreender toda a magia. As versões inferiores mais conhecidas possuem falhas que as tornam instáveis e exigem concentração, além de não incluírem as funções posteriores da versão verdadeira.",
