    "classes": "Druida, Ocultista, Spellblade, Bruxo, Mago",
    "ritual": false,
    "concentration": true,
    "desc": "Você escolhe uma criatura que possa ver dentro do alcance e tenta corromper o sangue dela. Criaturas sem sangue são imunes a este efeito. O alvo deve realizar um teste de resistência de Constituição. Em caso de falha, sofre 1d12 de dano de veneno e fica envenenado pela duração.\n\nNo fim de cada um dos turnos do alvo, ele pode repetir o teste de resistência de Constituição. Em caso de sucesso, a magia termina sobre ele. Em caso de falha, sofre mais 1d4 de dano de veneno enquanto a toxina continua a devastá-lo.",
    "higher": "Ao conjurar esta magia usando um espaço de magia de 2º nível ou superior, você pode escolher um alvo adicional para cada nível do espaço acima do 2º. Os alvos devem estar a até 9 metros uns dos outros quando forem escolhidos.",
    "traits": [],
