    "desc": "Você envolve uma arma corpo a corpo que esteja empunhando com ilusões. Ao conjurar a magia e, em cada um de seus turnos seguintes enquanto ela durar, você pode usar uma ação bônus para simular golpes com cópias ilusórias da lâmina. Essas fintas distraem um alvo e concedem vantagem ao seu próximo ataque com arma contra ele realizado antes do fim do turno. A magia termina antecipadamente se você soltar a arma usada na conjuração.\n\nComo uma ação, uma criatura que possa ver você pode realizar um teste de Inteligência (Investigação) contra a CD para evitar suas magias. Em caso de sucesso, você deixa de receber vantagem ao usar as lâminas ilusórias para realizar fintas contra essa criatura, tornando a magia ineficaz contra ela.",
