    "desc": "Você cria uma linha de espinheiros baixos que irrompe de um ponto que possa ver dentro do alcance. A linha tem 9 metros de comprimento por 1,5 metro de largura e é formada por seis quadrados de espinheiros de 1,5 metro. Cada quadrado deve estar conectado a outro e ser colocado sobre o chão.\n\nOs quadrados de espinheiros são terreno difícil. Uma criatura que entra em um deles sofre 4d4 de dano perfurante e deve realizar um teste de resistência de Constituição. Em caso de falha, seu deslocamento se torna 0 até o fim do turno.\n\nOs espinheiros murcham e morrem após 1 dia se a área não for apropriada para seu crescimento. Cada seção de 1,5 metro exige pelo menos 1 minuto para ser removida manualmente, ou pode ser destruída ao sofrer 5 ou mais pontos de dano de fogo. Todos os espinheiros se desfazem imediatamente em pó se você conjurar esta magia novamente.",
    "higher": "Ao conjurar esta magia usando um espaço de magia de 4º nível ou superior, você pode criar dois quadrados adicionais de espinheiros de 1,5 metro para cada nível do espaço acima do 3º.",
