    "concentration": false,
    "desc": "Você toca uma munição ou arma e a imbui com chamas mágicas ondulantes. Na primeira vez que atacar com o item fortalecido, ele irrompe em chamas brilhantes. Em caso de acerto, o alvo sofre 4d4 de dano de fogo adicional e começa a queimar. Em caso de erro, sofre metade desse dano e não começa a queimar.\n\nO alvo em chamas emite luz plena em um raio de 3 metros e penumbra por mais 3 metros, e sofre 1d4 de dano de fogo no fim de cada um de seus turnos, até que uma criatura use uma ação para apagar as chamas. Depois que um ataque for realizado com a munição ou arma, a magia termina.\n\nSe você tocar uma arma com a propriedade leve, pode realizar imediatamente um único ataque com ela como parte da mesma ação bônus usada para conjurar a magia.",
