    "ritual": false,
    "concentration": true,
    "desc": "Você escolhe quatro espaços desocupados que possa ver dentro do alcance. Plantas carnívoras enraizadas irrompem do solo, cada uma preenchendo um cubo de 1,5 metro. O chão a até 1,5 metro delas se torna terreno difícil.\n\nQuando as plantas surgem, cada uma ataca uma criatura à sua escolha a até 1,5 metro dela. Cada planta realiza um ataque corpo a corpo com magia, causando 2d8 de dano perfurante em caso de acerto. Faça uma jogada de ataque separada para cada planta.\n\nSe uma criatura terminar seu turno a até 1,5 metro de uma ou mais plantas carnívoras, as plantas atacam automaticamente essa criatura, a menos que você use sua reação para impedi-las. As plantas usam seu modificador de ataque com magia e causam 2d8 de dano perfurante em caso de acerto.\n\nCada planta possui CA 14, 30 pontos de vida e vulnerabilidade a dano de fogo e cortante. No início do seu turno, uma planta recupera todos os pontos de vida se ainda possuir pelo menos 1. Uma planta morre ao ser reduzida a 0 pontos de vida.\n\nQuando a magia termina, as plantas murcham e morrem, deixando terreno difícil para trás, exceto quando tiverem sido destruídas por dano de fogo.",
    "higher": "Ao conjurar esta magia usando um espaço de magia de 5º nível ou superior, você pode invocar uma planta carnívora adicional para cada nível do espaço acima do 4º.",
