    "ritual": true,
    "concentration": true,
    "desc": "Você tenta vincular a alma de uma criatura a uma boneca, criando uma ligação simpática entre as duas. O alvo deve realizar um teste de resistência de Carisma. Em caso de falha, fica vinculado à boneca. Em caso de sucesso, a criatura não é vinculada e a magia termina.\n\nComo parte da conjuração, quando a criatura falha no teste, e em seus turnos seguintes usando sua ação até a magia terminar, você pode realizar uma das manipulações abaixo:\n\n• Manter a boneca imóvel, fazendo com que a criatura fique impedida até o início do seu próximo turno.\n• Forçar a boneca a se mover, fazendo com que a criatura se desloque 4,5 metros em uma direção à sua escolha na qual ela seja capaz de se mover.\n• Perfurar a boneca, fazendo com que a criatura sofra 4d6 de dano perfurante.\n• Rasgar a boneca ao meio, encerrando a magia, destruindo a boneca e causando 4d12 de dano necrótico à criatura.\n\nA partir da segunda vez que você usar uma ação para manipular a boneca, depois que o efeito ocorrer, a criatura pode repetir o teste de resistência de Carisma com desvantagem. Em caso de sucesso, o efeito termina.\n\nUma criatura escolhida como alvo desta magia não pode ser escolhida novamente durante 24 horas.",
    "higher": "Quando conjurada com um espaço de magia de 5º nível ou superior, a magia passa a ter alcance ilimitado, desde que o alvo esteja no mesmo plano de existência que o conjurador.",
    "traits": [
      "Ritual"
    ],
    "category": "Magia do Compêndio",
    "source": "Kibbles' Casting Compendium v2.1 — p. 17",
    "sourceTitle": "Kibbles' Casting Compendium v2.1",
    "sourcePage": 17,
    "sourceNote": ""
