    "material": "",
    "duration": "1 rodada",
    "classes": "Spellblade, Mago",
    "ritual": false,
    "concentration": false,
    "desc": "Você cria uma singularidade gravitacional esmagadora em um ponto dentro do alcance. Ela permanece até o início do seu próximo turno. Ao conjurar a magia, cada criatura a até 4,5 metros do ponto deve realizar um teste de resistência de Força. Em caso de falha, é movida para o espaço disponível mais próximo adjacente à singularidade e sofre 6d6 de dano contundente. Em caso de sucesso, sofre metade do dano e não é arrastada para o centro.\n\nEnquanto estiver a até 4,5 metros da singularidade, uma criatura precisa gastar 2 metros de movimento para se afastar 1 metro dela.\n\nSe uma criatura terminar seu turno a até 4,5 metros da singularidade, deve realizar um teste de resistência de Força. Em caso de falha, sofre 2d6 de dano contundente e é arrastada novamente para o espaço disponível mais próximo do centro.",
    "higher": "Ao conjurar esta magia usando um espaço de magia de 4º nível ou superior, o dano aumenta em 1d6 para cada nível do espaço acima do 3º.",
    "traits": [],
