    "ritual": false,
    "concentration": false,
    "desc": "Você envolve sua mão em energia necrótica decadente, fazendo tudo que toca murchar e morrer. Realize um ataque corpo a corpo com magia contra uma criatura ou objeto ao alcance. Em caso de acerto, o alvo sofre 1d6 de dano necrótico e começa a descamar e se decompor.\n\nNa primeira vez que o alvo sofrer dano de outra fonte antes do início do seu próximo turno, ele sofre 1d6 de dano necrótico adicional. Alvos imunes a doenças são imunes a esse efeito.\n\nTanto o dano inicial quanto o dano secundário aumentam em 1d6 quando você alcança o 5º nível (2d6), o 11º nível (3d6) e o 17º nível (4d6).",
