    "concentration": false,
    "desc": "Você aponta para uma criatura dentro do alcance e tenta fazer o esqueleto dela se arrancar do próprio corpo. A criatura deve realizar um teste de resistência de Constituição. Em caso de falha, sofre 7d10 + 7 de dano necrótico; em caso de sucesso, sofre metade desse dano.\n\nSe esse dano matar a criatura, a carne se desprende do esqueleto e desaba em uma pilha. O esqueleto se torna um Esqueleto, usando as estatísticas das Regras Básicas, hostil a todas as criaturas vivas e atacando o alvo mais próximo.",
