    "concentration": true,
    "desc": "Sua sombra se alonga repentinamente, assumindo a forma de uma abominação devoradora horrível, e tenta consumir a sombra de uma criatura dentro do alcance. O alvo deve realizar um teste de resistência de Carisma.\n\nEm caso de falha, a sombra da criatura é devorada e ela sofre 6d6 de dano necrótico. Além disso, fica magicamente enfraquecida e subtrai 1d4 de suas jogadas de ataque, testes de resistência e testes de habilidade pela duração da magia, enquanto você soma 1d4 às suas próprias jogadas de ataque, testes de resistência e testes de habilidade. Em caso de sucesso, uma grande mordida é arrancada da sombra, o alvo sofre metade do dano e não fica enfraquecido.\n\nA magia falha se você ou o alvo não possuir sombra. Se a sombra do alvo for consumida, ele não projeta sombra até a magia terminar.",
    "higher": "Ao conjurar esta magia usando um espaço de magia de 5º nível ou superior, você pode escolher uma criatura adicional para cada nível do espaço acima do 4º. O bônus obtido ao consumir sombras nunca aumenta além de 1d4, mesmo que você consuma várias sombras.",
