    "higher": "Ao conjurar esta magia usando um espaço de magia de 3º nível ou superior, o dano-base aumenta em 1d8 para cada nível do espaço acima do 2º.\n\nPoderes de Tendência. Se o Mestre usar tendências para criaturas, pode decidir que o dano adicional se aplica a qualquer tipo de criatura cuja tendência moral seja oposta à do conjurador, maligna contra bondosa ou bondosa contra maligna. Como nem todos os cenários usam tendências de forma rígida, esta é uma regra variante a critério do Mestre.",
