    "desc": "Você tenta expurgar a magia que anima um constructo dentro do alcance, tornando-o inerte. O alvo sofre 4d10 de dano de força e deve ser bem-sucedido em um teste de resistência de Constituição ou fica atordoado por 1 minuto.\n\nNo fim de cada um de seus turnos, o alvo pode repetir o teste de resistência de Constituição. Em caso de sucesso, a magia termina sobre ele. Se o alvo possuir menos de 50 pontos de vida restantes quando falhar no teste, é reduzido a 0 pontos de vida.",
