    "duration": "Concentração, até 1 minuto",
    "classes": "Druida, Patrulheiro, Feiticeiro, Mago",
    "ritual": false,
    "concentration": true,
    "desc": "Escolha um ponto no chão que possa ver dentro do alcance. Um pequeno ciclone de poeira se forma nesse ponto, com 1,5 metro de raio e 9 metros de altura.\n\nUma criatura que começa seu turno no raio do ciclone ou entra nele pela primeira vez em seu turno deve realizar um teste de resistência de Força. Em caso de falha, sofre 1d12 de dano contundente e é empurrada 1,5 metro para longe do centro. Em caso de sucesso, sofre metade do dano e não é empurrada.\n\nComo uma ação bônus, você pode mover o ciclone até 9 metros em qualquer direção. Na primeira vez que fizer o raio dele atravessar uma criatura, ela deve realizar o teste de resistência contra o dano do ciclone e, em caso de falha, é empurrada para fora do caminho. Você pode continuar movendo o ciclone, mas sua força fica exaurida até o fim do turno, e outras criaturas não são afetadas quando ele as atravessa nesse mesmo turno.\n\nSe o ciclone passar sobre areia, poeira, terra solta ou cascalho pequeno, suga o material e deixa seu raio fortemente obscurecido até o início do seu próximo turno.",
