    "desc": "Você faz seus punhos irromperem em chamas. Pela duração, eles se tornam armas naturais simples que causam 1d6 de dano de fogo. Você é proficiente com essas armas, e elas possuem a propriedade leve.\n\nEnquanto a magia durar, qualquer objeto inflamável que você tentar segurar pega fogo. Se terminar seu turno agarrando outra criatura com as mãos, ela sofre 1d4 de dano de fogo. Você pode encerrar a magia antecipadamente sem usar uma ação.\n\nO dano causado a criaturas agarradas aumenta em 1d4 quando você alcança o 5º nível (2d4), o 11º nível (3d4) e o 17º nível (4d4).",
