    "desc": "Você se torna brevemente etéreo e intangível. Pela duração, pode se mover em qualquer direção e não cai. Pode atravessar criaturas, objetos, paredes, terreno e efeitos como se não existissem. Você só pode atravessar objetos mágicos se eles não bloquearem deslocamento etéreo.\n\nEnquanto estiver intangível, você é imune a todo dano, exceto dano de força.\n\nNo início do seu próximo turno, você volta a ser tangível e se manifesta no espaço atual. Se o espaço estiver ocupado, é deslocado para o espaço desocupado mais próximo e sofre dano de força igual ao dobro da quantidade de pés que foi forçado a se mover; para uso métrico, considere 2 pontos de dano para cada 30 centímetros deslocados. Se o espaço onde se manifesta não estiver no chão e você não puder voar, cai até o solo.",
    "higher": "",
    "traits": [
      "Arcana"
    ],
    "category": "Magia do Compêndio",
    "source": "Kibbles' Casting Compendium v2.1 — p. 26",
    "sourceTitle": "Kibbles' Casting Compendium v2.1",
    "sourcePage": 26,
    "sourceNote": ""
