    "classes": "Ocultista",
    "ritual": false,
    "concentration": true,
    "desc": "Você canaliza força profana em sua mão e tenta agarrar uma criatura. O alvo deve realizar um teste de resistência de Força. Em caso de falha, fica impedido pelo seu aperto mortal.\n\nNo turno dele, como uma ação, o alvo pode tentar escapar realizando um teste de Força (Atletismo) ou Destreza (Acrobacia) contra a CD para evitar suas magias.\n\nNo início do turno da criatura, enquanto você mantiver o agarre e a concentração, ela sofre 1d8 de dano necrótico enquanto você drena sua vida, e você recupera pontos de vida iguais à metade do dano causado.",
