    "classes": "Ocultista, Bruxo, Spellblade, Feiticeiro, Mago",
    "ritual": false,
    "concentration": true,
    "desc": "Você cria um ponto de vazio absoluto que engole uma esfera de 6 metros de raio, mergulhando-a em escuridão mágica e formando um vazio congelante que devora a vida. Uma criatura com visão no escuro não consegue enxergar através dessa escuridão, e luz não mágica não pode iluminá-la. Luz criada por uma magia só a ilumina se a magia tiver nível superior ao desta magia.\n\nUma criatura que começa seu turno dentro do vazio deve realizar um teste de resistência de Constituição. Em caso de falha, sofre 2d6 de dano de frio e 2d6 de dano necrótico, e seu deslocamento é reduzido em 1,5 metro. Essa redução permanece até que a criatura comece um turno fora da área e pode se acumular, mas nunca pode reduzir o deslocamento dela para menos de 1,5 metro. Em caso de sucesso, a criatura sofre metade do dano e não tem seu deslocamento reduzido.",
    "higher": "Ao conjurar esta magia usando um espaço de magia de 5º nível ou superior, tanto o dano de frio quanto o dano necrótico aumentam em 1d6, e a redução de deslocamento em uma falha aumenta para 3 metros, mantendo o mesmo limite mínimo de deslocamento.",
