    "desc": "Você faz uma muralha de terra de 4,5 metros de comprimento, 3 metros de altura e alguns centímetros de espessura irromper do chão. Ela concede cobertura total e bloqueia qualquer dano originado no lado oposto até ser destruída. Isso bloqueia ataques à distância e efeitos em área cujo ponto de origem esteja do outro lado da muralha, como o centro de uma magia de raio ou a origem de um cone ou linha.\n\nTodo dano bloqueado é aplicado à muralha, mesmo que normalmente afete apenas criaturas. Porém, ela sofre cada instância de dano bloqueado apenas uma vez, mesmo que esteja protegendo várias criaturas do mesmo efeito.\n\nA muralha possui pontos de vida iguais a 4d10 + seu modificador de habilidade de conjuração e se desfaz em pó ao ser reduzida a 0 pontos de vida. Qualquer dano restante depois de sua destruição é causado normalmente. Se não for destruída, ela se desfaz no início do seu próximo turno.",
    "higher": "Ao conjurar esta magia usando um espaço de magia de 4º nível ou superior, a muralha recebe 1d10 pontos de vida adicionais e fica 1,5 metro mais longa para cada nível do espaço acima do 3º.",
    "traits": [
      "Primal"
    ],
    "category": "Magia do Compêndio",
    "source": "Kibbles' Casting Compendium v2.1 — p. 30",
    "sourceTitle": "Kibbles' Casting Compendium v2.1",
