    "desc": "Um clarão parte da ponta de seu dedo até um ponto à sua escolha dentro do alcance e então se abre, com um rugido baixo, em uma explosão ilusória de chamas. Cada criatura à sua escolha em uma esfera de 6 metros de raio centrada nesse ponto deve realizar um teste de resistência de Sabedoria. Em caso de falha, sofre 6d6 de dano psíquico. Em caso de sucesso, percebe que o fogo é ilusório e não sofre dano.\n\nVocê pode fazer o efeito ilusório assumir a forma de uma explosão de gelo, relâmpagos ou energia de força pura, sem alterar o tipo de dano.",
    "higher": "Ao conjurar esta magia usando um espaço de magia de 4º nível ou superior, o dano aumenta em 1d6 para cada nível do espaço acima do 3º.\n\nAlvos à Sua Escolha. Diferentemente de uma bola de fogo verdadeira, a versão ilusória afeta apenas alvos escolhidos por você, sendo segura para uso entre aliados. Em compensação, causa menos dano e nenhum dano em um teste bem-sucedido, quando o alvo reconhece sua natureza ilusória.",
