    "duration": "Concentração, até 1 minuto",
    "classes": "Bardo, Ocultista, Feiticeiro, Bruxo, Mago",
    "ritual": false,
    "concentration": true,
    "desc": "Você cria um poço ilusório de 1,5 metro de raio em um ponto no chão que possa ver. As criaturas dentro do raio quando a magia é conjurada devem realizar um teste de resistência de Sabedoria.\n\nUma criatura que falhar acredita ter caído no poço, fica caída, não pode se levantar e fica cega para tudo que esteja além de 1,5 metro do poço ilusório. Ela pode usar sua ação para tentar escalar para fora, repetindo o teste de resistência de Sabedoria. Em caso de sucesso, gasta todo o seu deslocamento para se levantar, percebe que o poço é uma ilusão e encerra a magia sobre si. Em caso de falha, não consegue sair e continua acreditando estar presa.\n\nUma criatura afetada pode se mover dentro dos espaços cobertos pelo poço. Criaturas com deslocamento de voo não são afetadas. Sempre que uma criatura afetada sofrer dano, pode repetir o teste de resistência de Sabedoria.",
    "higher": "Ao conjurar esta magia usando um espaço de magia de 2º nível ou superior, o raio do poço aumenta em 1,5 metro para cada nível do espaço acima do 1º, até o máximo de 6 metros com um espaço de 4º nível.",
