    "classes": "Ocultista",
    "ritual": false,
    "concentration": true,
    "desc": "Você amaldiçoa um alvo para morrer. Os pontos de vida atuais e máximos dele são reduzidos em 3d10 + 10. Se isso reduzir uma criatura a 0 pontos de vida, ela morre.\n\nPela duração, o alvo não pode recuperar pontos de vida, exceto por uma magia conjurada usando um espaço de nível superior ao espaço usado nesta maldição. Além disso, qualquer teste contra a morte que ele realizar é automaticamente considerado como resultado 1.\n\nNo início de cada turno do alvo enquanto estiver sob o efeito, ele realiza um teste de resistência de Carisma. Em caso de falha, seus pontos de vida atuais e máximos são reduzidos em mais 1d10 + 10. Em caso de sucesso, a magia termina.\n\nOs pontos de vida máximos reduzidos por esta magia são restaurados quando a criatura termina um descanso longo.",
