    "classes": "Patrulheiro",
    "ritual": false,
    "concentration": false,
    "desc": "Você toca uma munição ou arma com a propriedade arremesso e a imbui de energia elétrica crepitante pela duração. Na primeira vez que atacar com o item fortalecido, ele se transforma em um raio e parte de você em uma linha de 30 metros de comprimento por 1,5 metro de largura. Faça a jogada de ataque da arma contra cada criatura nessa linha, usando a mesma rolagem contra todas elas. Se acertar, a criatura sofre 4d8 de dano elétrico; se errar, ela sofre metade desse dano. Essa rolagem de dano não recebe modificadores ou bônus associados a ataques com arma.\n\nO raio incendeia objetos inflamáveis na área que não estejam sendo vestidos ou carregados. Depois que um ataque for realizado com a munição ou arma, a magia termina.",
