    "desc": "Você aponta para uma criatura ou objeto Grande ou menor que não esteja sendo vestido nem carregado, ao alcance, e tenta derretê-lo até transformá-lo em uma poça de escória. Se o alvo for uma criatura, ela deve realizar um teste de resistência de Constituição. Se falhar, sofre 10d10 de dano de fogo; se obtiver sucesso, sofre metade desse dano.\n\nSe o alvo for um objeto, ele sofre 20d10 de dano de fogo. Se esse dano o reduzir a 0 pontos de vida, ele derrete e se transforma em uma poça de escória.",
