    "desc": "Um arco-íris vívido de luzes prismáticas dispara de sua mão. Cada criatura em um cone de 4,5 metros deve realizar um teste de resistência de Constituição.\n\nSe falhar, uma criatura fica cega e atordoada levemente até o final do seu próximo turno. Enquanto estiver afetada dessa forma, ela não pode realizar reações e seu deslocamento é reduzido à metade. Se falhar por 10 ou mais, ela também fica atordoada pela duração. Se obtiver sucesso, não fica cega, mas é momentaneamente desorientada pelo clarão e tem desvantagem nas jogadas de ataque até o final do seu turno.\n\nCriaturas que já estejam cegas ou não possam ver você não são afetadas, pois não enxergam a explosão de luz.",
