    "classes": "Bardo, Feiticeiro, Bruxo, Mago",
    "ritual": false,
    "concentration": false,
    "desc": "Você cria uma armadilha mágica, marcando-a sobre o próprio corpo, normalmente como um pequeno símbolo luminoso na pele. Na primeira vez que precisar realizar um teste de resistência contra uma magia de 1º nível ou inferior, essa magia é absorvida pela armadilha e nenhum de seus efeitos ocorre.\n\nNo seu próximo turno, você pode conjurar a magia absorvida sem gastar um espaço de magia. Caso não a conjure durante esse turno, a armadilha desaparece e a magia aprisionada é perdida.",
    "higher": "Ao conjurar esta magia usando um espaço de 3º nível ou superior, o nível máximo da magia que ela pode absorver aumenta em 1 para cada nível do espaço acima do 2º.\n\nObservação. A Armadilha Mágica absorve a primeira magia contra a qual você precise realizar um teste de resistência e que atenda aos critérios.",
    "traits": [],
    "category": "Magia do Compêndio",
    "source": "Kibbles' Casting Compendium v2.1 — p. 39",
