    "ritual": false,
    "concentration": false,
    "desc": "Você perfura um alvo com uma pequena presa mágica cheia de veneno. Realize um ataque corpo a corpo com magia contra uma criatura ao alcance. Se acertar, o alvo sofre 4d12 de dano de veneno e deve ser bem-sucedido em um teste de resistência de Constituição ou ficará envenenado por 1 minuto. No final de cada um de seus turnos, o alvo pode repetir o teste de resistência, deixando de estar envenenado em caso de sucesso.\n\nSe errar o ataque corpo a corpo, você pode manter concentração, como se estivesse se concentrando em uma magia, para preservar o ataque e tentar novamente até o final do seu próximo turno. Você pode continuar tentando até acertar ou perder a concentração.",
    "higher": "Ao conjurar esta magia usando um espaço de 4º nível ou superior, o dano aumenta em 1d12 para cada nível do espaço acima do 3º.",
