    "ritual": false,
    "concentration": false,
    "desc": "Você toca uma superfície de pedra ou o solo e convoca pedra que se molda conforme sua vontade. Você pode criar qualquer item de formato aproximado de tamanho Pequeno ou Minúsculo, incluindo armas corpo a corpo simples ou marciais funcionais para criaturas Médias ou menores. Os objetos possuem durabilidade mágica suficiente para resistir a se estilhaçar ou quebrar.\n\nAlternativamente, você pode envolver seus membros em pedra, fazendo seus ataques desarmados causarem 1d8 de dano de concussão pela duração do efeito.\n\nOs itens criados dessa maneira perdem sua durabilidade mágica depois de 1 hora e passam a quebrar facilmente caso seu formato normalmente não fosse funcional. Você pode manter até três itens ou efeitos criados por este truque ao mesmo tempo. Ao criar um quarto, o mais antigo perde sua durabilidade mágica e passa a quebrar facilmente.",
