    "ritual": false,
    "concentration": false,
    "desc": "Você faz um pilar de pedra se erguer do solo em um espaço que possa ver. O pilar tem 1,5 metro de diâmetro e sobe até 9 metros. O solo onde ele surge deve ser largo o bastante para acomodar seu diâmetro, e você pode escolher o solo sob uma criatura Média ou menor.\n\nSe o pilar for criado sob uma criatura, ela deve ser bem-sucedida em um teste de resistência de Destreza ou será erguida pelo pilar. Uma criatura pode escolher falhar nesse teste.\n\nCaso um teto ou outro obstáculo impeça o pilar de alcançar sua altura total, uma criatura sobre ele sofre 3d8 de dano de concussão e fica impedida, prensada entre o pilar e o obstáculo. A criatura impedida pode usar uma ação para realizar um teste de Força ou Destreza, à escolha dela, contra sua CD para evitar magia. Se obtiver sucesso, deixa de estar impedida e deve sair do pilar ou cair dele.\n\nO pilar possui CA 5 e 30 pontos de vida. Quando é reduzido a 0 pontos de vida, desmorona em escombros, criando uma área de terreno difícil de 3 metros de raio até que seja limpa. Cada porção de 1,5 metro de diâmetro da área exige ao menos 1 minuto de trabalho manual para ser removida.",
