    "classes": "Patrulheiro",
    "ritual": false,
    "concentration": false,
    "desc": "Você toca uma munição ou arma com a propriedade arremesso e a imbui com o poder de um furacão pela duração. Na primeira vez que atacar com o item fortalecido, ele libera uma rajada de vendaval que potencializa enormemente o disparo.\n\nSe acertar, o alvo sofre 4d8 de dano adicional do ataque e é empurrado 9 metros para trás. Qualquer criatura contra a qual o alvo colidir durante esse movimento sofre 2d8 de dano de concussão. Se errar, o alvo sofre metade do dano adicional e não é empurrado.\n\nDepois que um ataque for realizado com a munição ou arma, a magia termina.",
