    "ritual": false,
    "concentration": true,
    "desc": "Você cria uma esfera de ar giratório ao redor de uma criatura, fazendo-a lutar para respirar. O alvo deve realizar um teste de resistência de Constituição. Se falhar, perde 5d8 pontos de vida por falta de ar, tem desvantagem em todos os testes de habilidade e não pode falar. Se obtiver sucesso, perde metade dessa quantidade de pontos de vida e não sofre os outros efeitos.\n\nPela duração, você pode usar uma ação para obrigar a criatura a realizar novamente o teste de resistência contra a magia. Se o alvo falhar três vezes consecutivas, fica incapacitado até obter sucesso em um teste ou até a magia terminar. Se você não usar sua ação para obrigá-lo a realizar o teste em um turno, isso conta como um sucesso.\n\nUma criatura que não precise respirar não é afetada por esta magia.",
