    "ritual": false,
    "concentration": true,
    "desc": "Você faz ilusões de armadilhas mortais e perigos repentinos surgirem em um cubo de 18 metros originado em você. Lâminas balançam em correntes, espinhos brotam do chão, dardos disparam de pontos invisíveis, lava jorra do solo, plantas carnívoras ferozes atacam e outros perigos fantasmagóricos preenchem a mente de cada criatura à sua escolha na área.\n\nUma criatura afetada pode se mover com metade do deslocamento para evitar os perigos ou se mover normalmente, sofrendo 1d8 de dano psíquico para cada 1,5 metro percorrido dentro da área.\n\nQualquer criatura afetada que terminar o turno na área deve realizar um teste de resistência de Destreza. Se falhar, sofre 5d8 de dano psíquico; se obtiver sucesso, sofre metade desse dano. Sempre que sofrer dano por terminar o turno na área, a criatura pode realizar um teste de resistência de Sabedoria. Se obtiver sucesso, percebe que as armadilhas são falsas, e a área deixa de causar dano ou impedir seu movimento; para ela, todos os perigos passam a parecer imagens tênues e transparentes.\n\nCriaturas que você não escolheu para serem afetadas veem as armadilhas como imagens tênues e transparentes.",
