    "classes": "Mago",
    "ritual": false,
    "concentration": true,
    "desc": "Você convoca um lodo mágico. Ele se manifesta em um espaço desocupado que possa ver ao alcance e usa o bloco de estatísticas Espírito de Lodo. Ao conjurar a magia, escolha Verde, Vermelho ou Amarelo. A criatura se assemelha à opção escolhida, que determina certas características no bloco de estatísticas.\n\nA criatura desaparece quando é reduzida a 0 pontos de vida ou quando a magia termina. Ela é aliada sua e de seus companheiros. Em combate, compartilha sua contagem de iniciativa, mas realiza o turno imediatamente depois do seu. Ela obedece aos seus comandos verbais, sem exigir ação. Caso você não dê nenhum comando, ela realiza a ação Esquivar e usa seu movimento para evitar perigos.",
    "higher": "Ao conjurar esta magia usando um espaço de 2º nível ou superior, use o nível mais alto sempre que o nível da magia aparecer no bloco de estatísticas.\n\nESPÍRITO DE LODO\nLodo Pequeno, sem alinhamento\n\nClasse de Armadura: 6 + o nível da magia, armadura natural\nPontos de Vida: 5 + 10 para cada nível do espaço acima do 1º\nDeslocamento: 3 m\n\nFOR 12 (+3), DES 6 (-2), CON 12 (+1), INT 1 (-5), SAB 1 (-5), CAR 1 (-5)\n\nImunidades a Dano: ácido; fogo, apenas Vermelho; elétrico, apenas Amarelo; veneno, apenas Verde\nResistências a Dano: concussão, perfurante e cortante de ataques não mágicos\nSentidos: percepção às cegas 3 m, cego além desse raio; Percepção passiva 5\nIdiomas: compreende os idiomas que você fala\n\nAÇÕES\n\nAtaques Múltiplos. O lodo realiza uma quantidade de ataques igual à metade do nível da magia, arredondada para baixo.\n\nPseudópode. Ataque Corpo a Corpo com Arma: seu modificador de ataque com magia para atingir, alcance 1,5 m, um alvo. Acerto: 1d4 + 3 + o nível da magia de dano de ácido.",
