    "concentration": true,
    "desc": "Um tornado giratório irrompe, preenchendo um cilindro de 6 metros de raio e 12 metros de altura, centrado em um ponto ao alcance.\n\nQualquer criatura que começar o turno dentro do tornado deve realizar um teste de resistência de Força. Se falhar, sofre 4d8 de dano de concussão, é empurrada 3 metros para longe do centro e arremessada 12 metros para cima. Se obtiver sucesso, sofre metade desse dano e não é empurrada nem arremessada.\n\nComo uma ação bônus, você pode mover o tornado até 9 metros em qualquer direção. Ataques à distância com arma contra alvos a até 6 metros do tornado têm desvantagem, e qualquer ataque à distância que atravesse o tornado erra automaticamente.",
