    "classes": "Ocultista",
    "ritual": false,
    "concentration": true,
    "desc": "Você escolhe um ponto e convoca gavinhas, vinhas retorcidas e raízes nodosas de energia sombria, que irrompem do solo em um raio de 18 metros. Todas as criaturas à sua escolha na área devem realizar um teste de resistência de Destreza. Se falharem, ficam impedidas pelas gavinhas vegetais sombrias, que as agarram e drenam sua vida.\n\nNo início do turno de uma criatura impedida pela magia, ela sofre 2d10 de dano de concussão e 2d10 de dano necrótico. Sempre que uma criatura sofrer dano necrótico desta magia, você recupera 1d4 pontos de vida.\n\nUma criatura impedida pode usar sua ação para realizar um teste de Força ou Destreza, à escolha dela, contra sua CD para evitar magia. Se obtiver sucesso, liberta-se.\n\nUma gavinha pode ser destruída para libertar a criatura que segura. Cada gavinha possui CA 10, 20 pontos de vida e imunidade a todos os tipos de dano, exceto radiante e fogo. Magias que causem dano radiante ou de fogo em uma área também afetam as gavinhas nessa área.\n\nCriaturas que terminarem o turno dentro do raio sem estarem impedidas devem realizar um teste de resistência de Destreza. Se falharem, ficam impedidas pelas gavinhas.",
