    "ritual": false,
    "concentration": true,
    "desc": "Você conjura uma grande massa de água e a transforma em um funil giratório ao redor de um ponto no solo que possa ver. O funil preenche um cilindro de 3 metros de raio e 9 metros de altura.\n\nUma vez por turno, quando o espaço de uma criatura é completamente engolfado pela tromba-d'água, ela deve realizar um teste de resistência de Força. Se falhar, sofre 2d8 de dano de concussão, fica cega e surda e não pode falar. No início do próximo turno dela, é expelida da água para o espaço desocupado mais próximo. Se obtiver sucesso, sofre metade desse dano e nenhum dos outros efeitos.\n\nNo seu turno, você pode usar uma ação bônus para mover a tromba-d'água até 6 metros em qualquer direção ao longo do solo, engolfando criaturas em seu caminho. Uma criatura que falhar no teste depois de ser engolfada dessa maneira é carregada pelo movimento da tromba-d'água até ser expelida no início do turno dela, como normal.\n\nSe o ponto central da magia estiver sobre uma massa de água Enorme ou maior, o tamanho da tromba-d'água é dobrado.",
