    "ritual": false,
    "concentration": false,
    "desc": "Você assume o controle do sangue dentro de um cadáver Médio ou menor que tenha morrido no último minuto ou de uma criatura inconsciente desse tamanho.\n\nPela duração, como uma ação bônus, você pode fazer o cadáver ou a criatura se mover até 6 metros e realizar um único ataque corpo a corpo, usando seu modificador de habilidade de conjuração na jogada de ataque. Se o corpo estiver portando uma arma ou possuir uma arma natural, ele causa o dano dessa arma, sem receber modificadores especiais que a criatura viva possuía. Caso contrário, realiza uma pancada que causa 1d6, ou 1 ponto para uma criatura Minúscula, + seu modificador de habilidade de conjuração de dano.\n\nSe uma criatura que estava inconsciente recuperar a consciência durante a duração, ela pode realizar um teste de resistência de Carisma no final de cada um de seus turnos para retomar o controle do próprio corpo.\n\nVocê pode encerrar esta magia a qualquer momento, sem exigir uma ação.",
