    "desc": "Você conjura um enxame giratório de stirges mágicos em uma área de 6 metros de raio ao redor de um ponto ao alcance. Criaturas que possuam sangue, exceto você, que começarem o turno na área ou entrarem nela pela primeira vez em um turno devem realizar um teste de resistência de Destreza.\n\nSe falhar, uma criatura tem o sangue drenado pela tempestade de stirges, perde 4d4 + 12 pontos de vida e você recupera 4 pontos de vida. Se obtiver sucesso, ela perde metade dessa quantidade de pontos de vida e você recupera 2 pontos de vida.\n\nComo uma ação bônus em cada um de seus turnos pela duração da magia, você pode mover o enxame giratório de stirges até 9 metros em qualquer direção.",
