    "duration": "10 minutos",
    "classes": "Psion",
    "ritual": false,
    "concentration": false,
    "desc": "Você concede a uma criatura ao alcance um vislumbre do futuro. Role 1d4 para determinar o efeito:\n\n1 - Ação Futura. O alvo antevê uma ação que está por vir. Role 1d20 e anote o resultado. Até a duração terminar, o alvo pode substituir uma de suas rolagens de d20 pelo valor anotado.\n\n2 - A Própria Morte. O alvo vê a própria morte. Se for reduzido a 0 pontos de vida por um ataque ou por falhar em um teste de resistência durante a duração, ele evita o ataque ou obtém sucesso no teste, desde que não estivesse incapacitado antes de ser reduzido a 0.\n\n3 - Vitória Futura. O alvo vê uma vitória futura e ganha confiança. Ele recebe 10 pontos de vida temporários e fica imune à condição amedrontado pela duração.\n\n4 - Emboscada ou Surpresa. O alvo vê uma emboscada ou surpresa. Na primeira vez em que seria surpreendido, não é; ou, na primeira vez em que um ataque seria realizado contra ele com vantagem, o ataque é realizado com desvantagem em vez disso.\n\nDepois que qualquer um dos eventos previstos ocorrer, a habilidade termina.",
    "higher": "Ao usar esta habilidade gastando 3 ou mais pontos psi, você pode escolher o efeito em vez de rolar 1d4.\n\nA Morte Inevitável. No resultado 2, obter sucesso no teste nem sempre basta para impedir que o alvo seja reduzido a 0 pontos de vida. Algumas situações, como dano de queda, não envolvem teste de resistência nem ataque. Às vezes a vida simplesmente é assim.",
