    "material": "",
    "duration": "Concentração, até 1 minuto",
    "classes": "Psion",
    "ritual": false,
    "concentration": true,
    "desc": "Você libera o potencial da mente de uma criatura, permitindo que ela alcance plenamente seus limites. Pela duração, uma vez por turno, a criatura pode somar 1d4 a uma jogada de ataque, rolagem de dano ou teste de resistência que realizar.\n\nSempre que somar o d4, ela sofre 1 ponto de dano psíquico por forçar-se além de suas limitações naturais.",
    "higher": "",
